import{_ as a,o as s,c as n,a2 as o}from"./chunks/framework.BS0bAV7E.js";const m=JSON.parse('{"title":"Open Cube OS 架构","description":"","frontmatter":{},"headers":[],"relativePath":"zh/root/ARCHITECTURE.md","filePath":"zh/root/ARCHITECTURE.md"}'),c={name:"zh/root/ARCHITECTURE.md"};function l(i,e,r,t,d,p){return s(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="open-cube-os-架构" tabindex="-1">Open Cube OS 架构 <a class="header-anchor" href="#open-cube-os-架构" aria-label="Permalink to &quot;Open Cube OS 架构&quot;">​</a></h1><p>本文档描述了树中存在的 L0——下面列出的每个组件都是你可以打开的实 际文件。行数和每目录详情在 <code>docs/data/stats.json</code> 中（重新生成： <code>make api-docs</code>）。</p><h2 id="整体架构图" tabindex="-1">整体架构图 <a class="header-anchor" href="#整体架构图" aria-label="Permalink to &quot;整体架构图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                       GRUB 2.12 (hybrid BIOS + UEFI ISO)</span></span>
<span class="line"><span>                                     |  multiboot2 + kernel-as-module</span></span>
<span class="line"><span>        +----------------------------+----------------------------+</span></span>
<span class="line"><span>        |                 boot/boot.S                            |</span></span>
<span class="line"><span>        |   32-bit entry -&gt; GDT -&gt; 2 MiB identity map of the      |</span></span>
<span class="line"><span>        |   first 4 GiB -&gt; PAE+LME+PGE -&gt; long mode -&gt; kmain      |</span></span>
<span class="line"><span>        +----------------------------+----------------------------+</span></span>
<span class="line"><span>                                     |</span></span>
<span class="line"><span>   kernel/main.c  (kmain: bring-up order = the boot log you see)</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>   +----+------------+------------+-------------+------------+</span></span>
<span class="line"><span>   |                 |            |             |            |</span></span>
<span class="line"><span> kernel/arch/x86_64 kernel/core  kernel/mem   kernel/lib   kernel/crypto</span></span>
<span class="line"><span>   IDT/GDT/TSS      scheduler    PMM/VMM/heap string/tar  RSA/EC/AEAD/</span></span>
<span class="line"><span>   exceptions       syscalls 53   4 KiB pages  gzip/config  X.509/SHA</span></span>
<span class="line"><span>   IRQ 8259 remap   ring3+ELF    free-list     klog</span></span>
<span class="line"><span>   LAPIC/timers     signals      kmalloc</span></span>
<span class="line"><span>   context switch   soft timers</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>   +----------------+----------------+---------------+</span></span>
<span class="line"><span>   |                |                |               |</span></span>
<span class="line"><span> drivers/*        fs/              net/            shell/</span></span>
<span class="line"><span> 16 families      VFS + ramfs      e1000-family    parser/executor</span></span>
<span class="line"><span> block NVME AHCI  FAT32 exFAT      ARP IPv4 ICMP   233 commands</span></span>
<span class="line"><span> ATA DMA virtio   ext4             UDP DNS TCP     pipes/redirection</span></span>
<span class="line"><span> USB xHCI/EHCI/   node cache       sockets TLS     env/aliases</span></span>
<span class="line"><span> OHCI UHCI MSC    mount crossing   SSH client      line editor</span></span>
<span class="line"><span> HID audio serial congestion       sshd server    script lang</span></span>
<span class="line"><span> PCI PCIe ACPI    /etc volume      firewall        editor</span></span>
<span class="line"><span> I2C SMBus HPET                    tcp cc          TUI bridge</span></span>
<span class="line"><span> RTC TSC PM timer</span></span>
<span class="line"><span> wireless bt SD   tui/            chinese/        l1/</span></span>
<span class="line"><span> camera UVC IR    desktop,        CN console      162-numbered</span></span>
<span class="line"><span> gameport parallel menus, forms,  font 16x16      extension surface</span></span>
<span class="line"><span> SCSI LSI 53C8xx  editor, apps    pinyin IME      + solib loader</span></span></code></pre></div><h2 id="启动流程-串口日志显示的顺序" tabindex="-1">启动流程（串口日志显示的顺序） <a class="header-anchor" href="#启动流程-串口日志显示的顺序" aria-label="Permalink to &quot;启动流程（串口日志显示的顺序）&quot;">​</a></h2><ol><li>GRUB 加载 <code>boot/opencube.elf</code>（内核也作为标记为 <code>self</code> 的 multiboot2 模块附加—— 这是安装程序的模式，因此 <code>install</code>/<code>abdisk</code> 可以将<em>正在运行的</em>确切内核复制到磁盘）。</li><li><code>boot/boot.S</code>：32 位入口点，独立的 GDT，使用 2 MiB 页面对前 4 GiB 进行 身份映射，PAE + LME + PGE，切换到 64 位长模式，调用 <code>kmain</code>。</li><li><code>kernel/arch/x86_64/arch_multiboot2.c</code> 解析 multiboot2 信息 （帧缓冲、内存映射、命令行、ACPI RSDP 标签）——具有完整的畸形输入 防御：每标签最小值、NUL 终止检查、截断标签拒绝。</li><li><code>kmain</code> 按启动日志顺序点亮：帧缓冲控制台与字体， IDT/GDT/TSS（256 个门，#DF/#MC 和调试的 IST 栈）， 8259 PIC 重映射，100 Hz 的 PIT，PS/2 键盘，COM1 串口 RX， 行编辑器，异常（带有实时的 #DE/#UD/#PF 自检）， PMM，VMM，堆，然后是驱动域，VFS，网络，Shell。</li><li>Shell 注册其 233 个命令（<code>shell command system (233 commands)</code> 行），崩溃恢复启用，<code>oc&gt;</code> 提示符出现。</li></ol><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><ul><li><strong>PMM</strong> (<code>kernel/mem/mem_pmm.{c,h}</code>)：基于 multiboot2 内存映射的 4 KiB 页框位图分配器；保留区域（内核 代码、帧缓冲、mbi）在初始化时标记为已使用；O(1) 分配/释放。</li><li><strong>VMM</strong> (<code>kernel/mem/mem_vmm.{c,h}</code>)：4 级页表； 内核保持启动时前 4 GiB 的身份映射；API 创建并操作额外的地址空间（用户进程）。 页面保护标志映射到 rw/nx/user 位。</li><li><strong>Heap</strong> (<code>kernel/mem/mem_heap.{c,h}</code>)：kmalloc/kfree/krealloc/ kzalloc，带有首次适应和合并的空闲链表，16 字节 对齐的块（历史上 40 字节与 32 字节头部的错误教会了我们惨痛的教训）， 16 MiB 快速失败上限。</li><li><strong>#PF 增长</strong>：栈增长和堆增长的缺页异常是 <code>kmain</code> 异常路径中的 真实故障处理——非法访问升级到崩溃路径。</li></ul><h2 id="调度与时间" tabindex="-1">调度与时间 <a class="header-anchor" href="#调度与时间" aria-label="Permalink to &quot;调度与时间&quot;">​</a></h2><ul><li><strong>调度器</strong> (<code>kernel/core/core_sched.{c,h}</code>)：抢占式， 基于任务控制块进行优先级 + 时间片轮转； 上下文切换在 <code>arch/x86_64/arch_context_switch.S</code> 系列汇编中进行， 并通过 ABI 探测验证对齐。</li><li><strong>定时器</strong> (<code>kernel/core/core_timer.{c,h}</code>)：100 Hz 的 PIT 驱动 节拍，<code>g_boot_time_ms</code> 和软定时器轮。 HPET、ACPI PM 定时器和 TSC 作为<em>额外</em>时间源受支持 (<code>drivers/time/</code>)。</li><li><strong>看门狗</strong> (<code>kernel/core/core_watchdog.{c,h}</code>)：监控任务 槽位与超时策略（<code>watchdog</code> 命令），加上真正的 硬件看门狗点亮（如果固件提供）——Intel TCO （在 QEMU q35 上实时验证：PMBASE 发现，启用状态， 真正的硬重启 + 二次启动）和 ACPI WDAT 表。</li></ul><h2 id="中断与异常" tabindex="-1">中断与异常 <a class="header-anchor" href="#中断与异常" aria-label="Permalink to &quot;中断与异常&quot;">​</a></h2><p><code>kernel/arch/x86_64/arch_idt.{c,h}</code> + <code>arch_irq.c</code>：256 项 IDT， 带有 IST1（#DF/#MC 的 panic 栈）和 IST2（专用 异常退出栈——在 IST2 上从不发生上下文切换）的 TSS， 8259 重映射到向量 32-47，LAPIC 处理，以及完整的 异常帧路径，用于生成崩溃转储。每次启动都运行实时的 3/3（#DE/#UD/#PF）自检。</p><h2 id="ring-3、系统调用、进程" tabindex="-1">Ring 3、系统调用、进程 <a class="header-anchor" href="#ring-3、系统调用、进程" aria-label="Permalink to &quot;Ring 3、系统调用、进程&quot;">​</a></h2><ul><li><strong>系统调用 ABI</strong> (<code>kernel/core/core_syscall.h</code>)：<code>rax</code>=编号， <code>rdi/rsi/rdx/r10</code>=参数，<code>rax</code>=结果。53 个系统调用编号 （验证：<code>grep -c &#39;#define SYS_&#39; kernel/core/core_syscall.h</code>）。</li><li><strong>用户模式</strong> (<code>kernel/core/core_usermode.{c,h}</code>)：ELF 加载器， 进程表，信号，ring-3 入口/fork 汇编。</li><li><strong>用户程序</strong> (<code>userprogs/</code>)：hello，fork/exec/pipe/signal/ select/mmap 测试，使用真正的树内加载器进行动态链接 (<code>libs/ld_so.c</code>)——共享对象、<code>dlsym</code>、PIE 和重定位 测试都作为 shell 命令运行。</li></ul><h2 id="文件系统" tabindex="-1">文件系统 <a class="header-anchor" href="#文件系统" aria-label="Permalink to &quot;文件系统&quot;">​</a></h2><ul><li><strong>VFS</strong> (<code>fs/fs_vfs.{c,h}</code>)：统一的 open/read/write/seek/close/ stat/mkdir/rmdir/readdir/lookup 接口，适用于已注册的文件系统类型； 节点树透明地跨越挂载点；每个文件系统的大小写敏感性； 权限位强制执行；i64 寻址。</li><li><strong>文件系统</strong>：FAT32（LFN 与别名 + 冲突扫描 + 校验和 验证，双 FAT 镜像，FSINFO），exFAT（活动 FAT）， ext4（读/写，支持扩展），ramfs（稀疏洞归零）。</li><li><strong>块层</strong> (<code>drivers/block/driver_block_blk.{c,h}</code>)：注册/ 读/写/刷新，支持每个实例的名称，分区扫描， AHCI，ATA/ATA-DMA（32 字节堆头保证 PRDT 对齐）， NVMe，virtio-blk。</li><li><strong>/etc 卷</strong>：挂载在 /etc 的 32 MiB FAT32 镜像， 包含 <code>opencube.conf</code>、SSH 主机密钥、内核日志—— 因此配置在重启后仍然保留（<code>etc.img</code> 目标）。</li></ul><h2 id="网络协议栈" tabindex="-1">网络协议栈 <a class="header-anchor" href="#网络协议栈" aria-label="Permalink to &quot;网络协议栈&quot;">​</a></h2><p><code>net/net_core.{c,h}</code> 及相关模块——一个自包含的协议栈：PCI 发现，e1000 系列网卡驱动（e1000/e1000e/igb/ixgbe；rtl8139/ rtl8169 系列；BCM57xx），Ethernet + ARP + IPv4 + ICMP + UDP + DNS + TCP 及拥塞控制（<code>net_tcp_cc.c</code>），用户程序的 套接字 API，状态防火墙，<code>wget</code>/<code>dns</code>/<code>ping</code>/<code>route</code> 命令。 在其之上：支持 RSA/ECDHE、X.509 链验证（RFC 6125 主机名策略） 的 TLS 1.2/1.3 客户端，以及真正的 SSH 客户端 + SSH 服务器 (<code>net_sshd.c</code>，通过 curve25519/ed-style 原语进行密钥交换， 主机密钥在 /etc)。DRBG 播种是 RDRAND + 重新混合的 RDTSC（NIST SP 800-90A HMAC_DRBG）。</p><h2 id="驱动" tabindex="-1">驱动 <a class="header-anchor" href="#驱动" aria-label="Permalink to &quot;驱动&quot;">​</a></h2><p><code>drivers/</code> 下的 16 个驱动家族——每个在 <code>docs/drivers/</code> 下都有 自己的点亮手册。亮点：UHCI/OHCI/EHCI/xHCI USB 栈， 支持 MSC（大容量存储）、HID、串口、音频类； HDA/AC97/SB16/ES1370/virtio 声卡；i2c + SMBus； 无线（ath/brcm/iwlwifi/rtlwifi 系列）和蓝牙（HCI/L2CAP/RFCOMM/SDP/SPP + HID）层； 支持 MJPEG 的 UVC 摄像头；SD/SDHCI；SCSI（LSI 53C8xx 系列）； 带有真正 AML 命名空间遍历器的 ACPI（FADT/DSDT/MCFG， S3 挂起/恢复在 <code>arch_acpi_s3*.S</code> 中）；芯片组时间源 （HPET/PM 定时器/TSC/CMOS RTC）。</p><h2 id="shell-与-tui" tabindex="-1">Shell 与 TUI <a class="header-anchor" href="#shell-与-tui" aria-label="Permalink to &quot;Shell 与 TUI&quot;">​</a></h2><ul><li><strong>Shell</strong> (<code>shell/</code>)：分词器，环境变量，别名，管道， 重定向，后台作业，通配符，命令链 (<code>;</code> <code>&amp;&amp;</code> <code>||</code>)，当前工作目录，脚本语言， <code>help -a/-w</code> 两种视图，233 个命令，带历史记录的 行编辑器，文本 <code>editor</code>。</li><li><strong>TUI</strong> (<code>tui/</code>)：在帧缓冲之上的窗口层—— 带有任务栏/启动器的桌面，菜单，表单，面板，文本控件， TUI 编辑器，系统监控应用，以及扩展接口面 <code>tui/tui_ext.h</code>（37 个可调用声明），L1 模块使用。</li></ul><h2 id="中文控制台层" tabindex="-1">中文控制台层 <a class="header-anchor" href="#中文控制台层" aria-label="Permalink to &quot;中文控制台层&quot;">​</a></h2><p><code>chinese/</code> 添加了 16x16 位图字体，GB 编码的控制台渲染， 拼音输入法，以及 TUI 硬件/网络/系统信息应用的中文变体—— 可在构建时选择（<code>CONFIG_CHINESE</code>），禁用时使用 ASCII 等价回退。系统字符串按约定保持 ASCII。</p><h2 id="l1-扩展接口面" tabindex="-1">L1 扩展接口面 <a class="header-anchor" href="#l1-扩展接口面" aria-label="Permalink to &quot;L1 扩展接口面&quot;">​</a></h2><p>编号的 162 接口面（参见 <code>INTERFACES.md</code>）加上驱动/OTA/看门狗/健康/内核日志头文件； 共享对象加载器（<code>libs/ld_so.c</code>）让 L1 模块在运行时加载。 TUI 命令桥端到端地演示了该模式。</p><h2 id="ota-与-a-b-更新" tabindex="-1">OTA 与 A/B 更新 <a class="header-anchor" href="#ota-与-a-b-更新" aria-label="Permalink to &quot;OTA 与 A/B 更新&quot;">​</a></h2><p><code>kernel/ota/</code>：更新清单验证（SHA256 + 签名）， 下载，分阶段安装到 A/B 槽位（<code>ota_ab.{c,h}</code>）， 回滚，GRUB 菜单消耗的启动槽位标志（槽位 ISO / A / B）。 <code>update</code> 命令链运行整个流程；<code>ab_partition_test</code> 在临时磁盘上练习槽位管理。</p><h2 id="崩溃恢复" tabindex="-1">崩溃恢复 <a class="header-anchor" href="#崩溃恢复" aria-label="Permalink to &quot;崩溃恢复&quot;">​</a></h2><p><code>kernel/core/core_crash.c</code> + <code>shell/shell_cmds_crash.c</code>：panic 路径， 将寄存器转储到串口 + /etc 卷上的崩溃日志， 通过 <code>dumpinfo</code> 检查转储，客户机内的 <code>crashtest</code>， 以及 WinRE 风格的恢复姿态：系统默认启动到 <code>oc&gt;</code> shell， 因此&quot;恢复&quot;是主要接口，而不是特殊模式。</p>`,30)])])}const u=a(c,[["render",l]]);export{m as __pageData,u as default};
